	CONSTRAINT ck_scoreboard_review_counts CHECK (matched_count >= 0 AND manual_count >= 0 AND corrected_count >= 0 AND unexplained_count >= 0), 
	FOREIGN KEY(legacy_source_artifact_id) REFERENCES source_artifacts (artifact_id) ON DELETE RESTRICT, 
