	total_stake FLOAT NOT NULL, 
	currency TEXT NOT NULL, 
	account_id TEXT NOT NULL, 
	ticket_kind TEXT, 
	stake_minor INTEGER, 
	fixed_prize_policy_revision_id TEXT, 
	PRIMARY KEY (ticket_id), 
	CONSTRAINT ck_tickets_v2_shape CHECK ((ticket_kind IS NULL AND stake_minor IS NULL AND fixed_prize_policy_revision_id IS NULL) OR (ticket_kind IN ('jczq_pass', 'sfc', 'renjiu') AND stake_minor > 0 AND ((ticket_kind = 'jczq_pass' AND fixed_prize_policy_revision_id IS NULL) OR (ticket_kind IN ('sfc', 'renjiu') AND fixed_prize_policy_revision_id IS NOT NULL)))), 
	FOREIGN KEY(proposal_id) REFERENCES ticket_proposals (proposal_id) ON DELETE RESTRICT, 
	FOREIGN KEY(account_id) REFERENCES cash_accounts (account_id) ON DELETE RESTRICT, 
	FOREIGN KEY(fixed_prize_policy_revision_id) REFERENCES zucai_fixed_prize_policy_revisions (fixed_prize_policy_revision_id) ON DELETE RESTRICT
);

